const d = $input.first().json.body ?? $input.first().json;
const ventas = Array.isArray(d.ventas) ? d.ventas : [];

const porCategoria = {};
for (const v of ventas) {
  const cat = String(v.categoria ?? 'sin categoría');
  const total = Number(v.cantidad ?? 0) * Number(v.precio ?? 0);
  if (!porCategoria[cat]) porCategoria[cat] = { categoria: cat, unidades: 0, total: 0 };
  porCategoria[cat].unidades += Number(v.cantidad ?? 0);
  porCategoria[cat].total += total;
}

const categorias = Object.values(porCategoria)
  .map(c => ({ ...c, total: Math.round(c.total * 100) / 100 }))
  .sort((a, b) => b.total - a.total);

const totalGeneral = Math.round(categorias.reduce((s, c) => s + c.total, 0) * 100) / 100;
return [{ json: { cantidadVentas: ventas.length, totalGeneral, categoriaTop: categorias[0]?.categoria ?? null, categorias } }];
